What number is printed when this program runs?

```python
def process(items):
    result = {}
    for i, item in enumerate(items):
        key = item % 3
        if key in result:
            result[key].append(i)
        else:
            result[key] = [i]
    return result

r = process([5, 9, 7, 2, 12, 4, 8])
total = 0
for k, v in r.items():
    total += k * sum(v)
print(total)
